async def check_update(dev: Device, internet: bool, update: bool):
    """Print out update information."""
    if dev.is_update_available() and update:
        print(f"Update available: {dev.update_info.version}")
        if internet:
            dev.update()
            print("Update successful")
        else:
            print("No internet connection, update failed")

